import pathlib,urllib.request,urllib.error,json,datetime
api='https://app.ontrackegy.com/device/v1/'
log=pathlib.Path('/home/appontrack/public_html/device/v1/error_log')
before=log.stat().st_size if log.exists() else 0
tests=[('get_unprivileged',None),('post_no_token',json.dumps({'operation':'voice_session'}).encode('utf8')),('event_no_token',json.dumps({'operation':'workspace_call_event','call_id':'00000000-0000-4000-8000-000000000000','sequence':1,'phase':'ringing'}).encode('utf8'))]
out=[]
for name,payload in tests:
 try:
  kwargs={'headers':{'User-Agent':'OnTrack-P0-Device-HTTP500-Regression/1.0','Cache-Control':'no-cache'}}
  if payload is not None:
   kwargs['data']=payload;kwargs['headers']['Content-Type']='application/json'
  req=urllib.request.Request(api,**kwargs)
  with urllib.request.urlopen(req,timeout=9) as res:status=res.status;body=res.read(500).decode('utf8','replace')
 except urllib.error.HTTPError as ex:status=ex.code;body=ex.read(500).decode('utf8','replace')
 except Exception as ex:status=0;body=type(ex).__name__
 try:response=json.loads(body)
 except:response={'unexpected_response':body[:120]}
 out.append({'test':name,'status':status,'error':response.get('error',''),'ok':(status==405 if name=='get_unprivileged' else status==401)})
after=log.stat().st_size if log.exists() else 0
additional=''
if after>before:
 with log.open('rb') as fp:fp.seek(before);additional=fp.read(4000).decode('utf8','replace')
fresh_fatal='Cannot redeclare' in additional or 'PHP Fatal error' in additional
print(json.dumps({'checks':out,'all_pass':all(t['ok'] for t in out),'new_fatal_error':fresh_fatal,'error_log_bytes_added':max(0,after-before)},ensure_ascii=False))
if not all(t['ok'] for t in out) or fresh_fatal:raise SystemExit(2)
